/// Integer field initialisers each monster class's `.ctor` stores before its
/// base constructor call, as `(field, value)` sorted by field. Ascending by
/// `MonsterKind`; only kinds with such a store have a row.
#[rustfmt::skip]
pub static MONSTER_CTOR_INTS: [(MonsterKind, &[(&str, i64)]); 3] = [
    (MonsterKind::DevotedSculptor, &[("_ritualGain", 9)]),
    (MonsterKind::LivingFog, &[("_bloatAmount", 1)]),
    (MonsterKind::TwoTailedRat, &[("_starterMoveIndex", -1), ("_turnsUntilSummonable", 2)]),
];

/// The integer `kind`'s `.ctor` initialises `field` to, when `MONSTER_CTOR_INTS`
/// carries it.
pub fn monster_ctor_int(kind: MonsterKind, field: &str) -> Option<i64> {
    let index = MONSTER_CTOR_INTS
        .binary_search_by_key(&(kind as u16), |(k, _)| *k as u16)
        .ok()?;
    MONSTER_CTOR_INTS[index]
        .1
        .iter()
        .find(|(name, _)| *name == field)
        .map(|(_, value)| *value)
}

