/// One ENCOUNTER class's literal `Rng::NextInt` bounds on the per-fight
/// Encounter stream, in `GenerateMonsters` body order.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct EncounterRngDraws {
    /// The ModelId entry of the ENCOUNTER class.
    pub entry: &'static str,
    /// `[lo, hi)` per draw — `NextInt(max)` is `(0, max)`.
    pub draws: &'static [(i32, i32)],
    /// Why the bounds could not be read; empty when they were.
    pub refused: &'static str,
}

/// Every ENCOUNTER class whose own `GenerateMonsters` spends a `NextInt`
/// on `EncounterModel::get_Rng`, ascending by entry. Read out of the
/// assembly, never hand-transcribed.
#[rustfmt::skip]
pub static ENCOUNTER_RNG_DRAWS: [EncounterRngDraws; 5] = [
    EncounterRngDraws { entry: "DECIMILLIPEDE_ELITE", draws: &[(0, 3)], refused: "" },
    EncounterRngDraws { entry: "PUNCH_OFF_EVENT_ENCOUNTER", draws: &[(2, 10), (2, 10)], refused: "" },
    EncounterRngDraws { entry: "SCROLLS_OF_BITING_NORMAL", draws: &[(0, 3)], refused: "" },
    EncounterRngDraws { entry: "SCROLLS_OF_BITING_WEAK", draws: &[(0, 3)], refused: "" },
    EncounterRngDraws { entry: "TWO_TAILED_RATS_NORMAL", draws: &[(0, 3)], refused: "" },
];

