/// Registry rows the generator refused to transcribe, as
/// `(site, reason)`. Empty is the healthy state; a non-empty
/// table is an explicit I5 refusal, never a silent drop.
#[rustfmt::skip]
pub static REFUSED_CONTENT: [(&str, &str); 2] = [
    ("pool:_BATCH172_CHARACTER_CARD_POOLS", "keyed pool values are not tuples of CardIds"),
    ("pool:_BATCH172_REWARD_POOLS", "pool members are not CardIds: ['Defect', 'Ironclad', 'Necrobinder', 'Regent']"),
];

#[cfg(test)]
#[rustfmt::skip]
mod tests {
    use super::*;

    #[test]
    fn card_rows_are_sorted_and_complete() {
        assert_eq!(CARD_ROWS.len(), 1153);
        assert!(CARD_ROWS
            .windows(2)
            .all(|w| (w[0].id as u16, w[0].upgrade)
                < (w[1].id as u16, w[1].upgrade)));
        for row in CARD_ROWS.iter() {
            assert_eq!(card_row(row.id, row.upgrade), Some(row));
        }
    }

    #[test]
    fn card_type_metadata_has_the_complete_six_way_census() {
        assert_eq!(CardType::ALL.len(), 6);
        assert_eq!(CARD_ROWS.iter().filter(|row| row.card_type == CardType::Attack).count(), 396);
        assert_eq!(CARD_ROWS.iter().filter(|row| row.card_type == CardType::Skill).count(), 492);
        assert_eq!(CARD_ROWS.iter().filter(|row| row.card_type == CardType::Power).count(), 226);
        assert_eq!(CARD_ROWS.iter().filter(|row| row.card_type == CardType::Status).count(), 17);
        assert_eq!(CARD_ROWS.iter().filter(|row| row.card_type == CardType::Curse).count(), 18);
        assert_eq!(CARD_ROWS.iter().filter(|row| row.card_type == CardType::Quest).count(), 4);
    }

    #[test]
    fn native_unplayable_rows_are_exact_and_distinct_from_can_play() {
        assert_eq!(NATIVE_UNPLAYABLE_CARD_ROWS.len(), 27);
        assert!(NATIVE_UNPLAYABLE_CARD_ROWS.windows(2).all(|w|
            (w[0].0 as u16, w[0].1) < (w[1].0 as u16, w[1].1)));
        for &(id, upgrade) in NATIVE_UNPLAYABLE_CARD_ROWS.iter() {
            assert!(card_has_native_unplayable_keyword(id, upgrade));
        }
        assert!(card_has_native_unplayable_keyword(CardId::Dazed, 0));
        assert!(card_has_native_unplayable_keyword(CardId::Normality, 0));
        assert!(card_has_native_unplayable_keyword(CardId::SpoilsMap, 0));
        assert!(!card_has_native_unplayable_keyword(CardId::Sloth, 0));
        assert!(!card_has_native_unplayable_keyword(CardId::Enthralled, 0));
    }

    #[test]
    fn card_rarity_metadata_has_the_complete_derived_census() {
        assert_eq!(CardRarity::ALL.len(), 10);
        assert_eq!(CardId::ALL.iter().filter(|id| card_rows(**id)[0].rarity == CardRarity::Ancient).count(), 19);
        assert_eq!(CardRarity::Ancient.as_str(), "ancient");
        assert_eq!(CardId::ALL.iter().filter(|id| card_rows(**id)[0].rarity == CardRarity::Basic).count(), 19);
        assert_eq!(CardRarity::Basic.as_str(), "basic");
        assert_eq!(CardId::ALL.iter().filter(|id| card_rows(**id)[0].rarity == CardRarity::Common).count(), 100);
        assert_eq!(CardRarity::Common.as_str(), "common");
        assert_eq!(CardId::ALL.iter().filter(|id| card_rows(**id)[0].rarity == CardRarity::Curse).count(), 18);
        assert_eq!(CardRarity::Curse.as_str(), "curse");
        assert_eq!(CardId::ALL.iter().filter(|id| card_rows(**id)[0].rarity == CardRarity::Event).count(), 19);
        assert_eq!(CardRarity::Event.as_str(), "event");
        assert_eq!(CardId::ALL.iter().filter(|id| card_rows(**id)[0].rarity == CardRarity::Quest).count(), 4);
        assert_eq!(CardRarity::Quest.as_str(), "quest");
        assert_eq!(CardId::ALL.iter().filter(|id| card_rows(**id)[0].rarity == CardRarity::Rare).count(), 160);
        assert_eq!(CardRarity::Rare.as_str(), "rare");
        assert_eq!(CardId::ALL.iter().filter(|id| card_rows(**id)[0].rarity == CardRarity::Status).count(), 17);
        assert_eq!(CardRarity::Status.as_str(), "status");
        assert_eq!(CardId::ALL.iter().filter(|id| card_rows(**id)[0].rarity == CardRarity::Token).count(), 10);
        assert_eq!(CardRarity::Token.as_str(), "token");
        assert_eq!(CardId::ALL.iter().filter(|id| card_rows(**id)[0].rarity == CardRarity::Uncommon).count(), 230);
        assert_eq!(CardRarity::Uncommon.as_str(), "uncommon");
        for id in CardId::ALL {
            let rows = card_rows(id);
            assert!(!rows.is_empty(), "{}", id.as_str());
            assert!(rows.iter().all(|row| row.rarity == rows[0].rarity),
                "rarity drifted across upgrades for {}", id.as_str());
        }
    }

    #[test]
    fn every_card_id_has_at_least_one_row() {
        for id in CardId::ALL.iter() {
            assert!(!card_rows(*id).is_empty(), "{}", id.as_str());
        }
    }

    #[test]
    fn keyed_tables_are_sorted_for_binary_search() {
        assert!(LOOPS.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(RANDOM_MOVES.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(FABRICATOR_BOT_MOVES
            .windows(2)
            .all(|w| w[0].0 < w[1].0));
        assert!(TEMPLATE_RELIC_STEPS
            .windows(2)
            .all(|w| w[0].0 < w[1].0));
    }

    #[test]
    fn generation_pools_are_pinned() {
        assert_eq!(GENERATION_POOLS.len(), 21);
        for (name, pool) in GENERATION_POOLS.iter() {
            assert!(!name.is_empty());
            assert!(pool.iter().all(|c| CardId::from_str(c.as_str()) == Some(*c)));
        }
    }

    /// I5: a non-empty refusal table is a real event. This
    /// pins the count so a new refusal cannot land silently.
    #[test]
    fn refusal_count_is_pinned() {
        assert_eq!(REFUSED_CONTENT.len(), 2);
        assert_eq!(DYNAMIC_MONSTER_SITES.len(), 9);
    }
    #[test]
    fn relic_ledger_partition_is_exact() {
        assert_eq!(RELIC_LEDGER.len(), 299);
        assert_eq!(CENSUS_INERT_RELICS.len(), 117);
        assert_eq!(EFFECTIVE_TEMPLATE_RELICS.len(), 18);
        assert_eq!(HAND_AUTHORED_ACTIVE_RELICS.len(), 164);
        assert_eq!(RAW_TEMPLATE_OVERLAP_RELICS.len(), 16);

        let mut inert_count = 0;
        let mut template_only_count = 0;
        let mut hand_active_count = 0;
        let mut admitted_count = 0;
        let mut implemented_count = 0;
        let mut compiled_template_count = 0;
        let mut raw_template_count = 0;

        for (idx, row) in RELIC_LEDGER.iter().enumerate() {
            assert_eq!(row.id as usize, idx);
            assert_eq!(relic_ledger_row(row.id), row);
            assert_eq!(row.id.as_str(), row.name);
            assert!(row.inventory_represented);

            if row.in_raw_templates {
                raw_template_count += 1;
            }
            if row.compiled_template {
                compiled_template_count += 1;
            }
            if row.implemented {
                implemented_count += 1;
            }
            if row.exactly_admitted {
                admitted_count += 1;
            }

            match row.classification {
                RelicClassification::CensusInert => {
                    inert_count += 1;
                    assert!(CENSUS_INERT_RELICS.binary_search(&row.id).is_ok());
                    assert!(!row.in_effective_templates);
                    assert!(!row.compiled_template);
                    assert!(!row.implemented);
                    assert!(row.exactly_admitted);
                }
                RelicClassification::TemplateOnly => {
                    template_only_count += 1;
                    assert!(EFFECTIVE_TEMPLATE_RELICS.binary_search(&row.id).is_ok());
                    assert!(row.in_raw_templates);
                    assert!(row.in_effective_templates);
                    assert!(row.compiled_template);
                    assert_eq!(row.implemented, row.exactly_admitted);
                }
                RelicClassification::HandAuthoredActive => {
                    hand_active_count += 1;
                    assert!(HAND_AUTHORED_ACTIVE_RELICS.binary_search(&row.id).is_ok());
                    assert!(!row.in_effective_templates);
                    assert!(!row.compiled_template);
                    if row.implemented {
                        assert!(row.exactly_admitted);
                    } else {
                        assert!(!row.exactly_admitted);
                    }
                }
            }
        }

        assert_eq!(inert_count, 117);
        assert_eq!(template_only_count, 18);
        assert_eq!(hand_active_count, 164);
        assert_eq!(raw_template_count, 34);
        assert_eq!(compiled_template_count, 18);
        assert_eq!(implemented_count, 182);
        assert_eq!(admitted_count, 299);
    }

    #[test]
    fn sculpting_strike_row_matches_registry() {
        let row = card_row(CardId::SculptingStrike, 0).unwrap();
        assert_eq!(row.cost, 1);
        assert_eq!(row.name, "SCULPTING_STRIKE");
        assert_eq!(row.steps.len(), 2);
        assert!(row.strike_tag);
        assert_eq!(row.steps[0].kind, StepKind::Attack);
        assert_eq!(row.steps[0].args, &[Arg::I(9), Arg::I(1)]);
        assert_eq!(row.steps[1].kind, StepKind::Select);
        assert_eq!(row.steps[1].args, &[Arg::S("hand"), Arg::I(1), Arg::I(1), Arg::S("without_ethereal_keyword"), Arg::S("apply_permanent_ethereal")]);
    }

    #[test]
    fn terror_eel_loop_matches_registry() {
        let moves = monster_loop(MonsterKind::TerrorEel).unwrap();
        assert_eq!(moves.len(), 2);
        assert_eq!(moves[0].name, "CRASH");
        assert_eq!(moves[0].kind, MoveKind::Attack);
        assert_eq!(moves[0].args, &[Arg::Tier(move_constants::TERROR_EEL_CRASH_DAMAGE), Arg::I(1)]);
        assert_eq!(moves[0].repeats, Repeats::Absent);
        assert_eq!(moves[1].name, "THRASH");
        assert_eq!(moves[1].kind, MoveKind::AttackVigor);
        assert_eq!(moves[1].args, &[Arg::Tier(move_constants::TERROR_EEL_THRASH_DAMAGE), Arg::I(3), Arg::I(6)]);
        assert_eq!(moves[1].repeats, Repeats::Absent);
    }

    #[test]
    fn leaf_slime_goop_move_is_a_typed_card_key() {
        let moves = random_moves(MonsterKind::LeafSlimeS).unwrap();
        let goop = moves
            .iter()
            .find(|m| m.name == "GOOP_MOVE")
            .expect("GOOP_MOVE");
        assert_eq!(goop.kind, MoveKind::AddStatusDiscard);
        assert_eq!(goop.args, &[Arg::List(&[Arg::Card(CardId::Slimed), Arg::I(0)]), Arg::I(1)]);
    }
}
